(()=>{const ids=['packPrice','packCount','runtime'];const update=()=>{const [price,count,time]=ids.map(id=>Number(document.getElementById(id).value));const out=document.getElementById('valueResult');if(!(price>0&&count>=1&&Number.isInteger(count)&&time>0)){out.textContent='Enter a positive price and runtime, and a whole-number cell count.';return;}const unit=price/count;out.textContent=`Per cell: KRW ${unit.toLocaleString('en-US',{maximumFractionDigits:1})} · KRW/hour: ${(unit/time).toLocaleString('en-US',{maximumFractionDigits:2})} · Hours per KRW 100: ${(100*time/unit).toLocaleString('en-US',{maximumFractionDigits:2})}`;};ids.forEach(id=>document.getElementById(id).addEventListener('input',update));update();})();
